/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

void bus_status_notify_input_keyless_lock (void *arg)
{
	d2d_tx(SET_KEYLESS_ARM);
	bus_status_arm = 1;
}

//--------------------------------------------------------------------------//

void bus_status_notify_input_keyless_unlock (void *arg)
{
	d2d_tx(SET_KEYLESS_DISARM);
	bus_status_arm = 0;
}

